changeSet.sql:
INSERT INTO construction_material_packages (construction_material_id, offer_package_id)
SELECT DISTINCT cm.id, op.id FROM work_material_consumptions wmc JOIN construction_material_types cmt ON cmt.id=wmc.construction_material_type_id JOIN offer_packages op ON op.id=wmc.offer_package_id JOIN construction_materials cm ON cm.type_id=cmt.id AND cm.active
WHERE wmc.branch='construction' AND NOT EXISTS (SELECT 1 FROM construction_materials cm2 JOIN construction_material_packages cmp ON cmp.construction_material_id=cm2.id WHERE cm2.active AND cm2.type_id=wmc.construction_material_type_id AND cmp.offer_package_id=wmc.offer_package_id) AND NOT EXISTS (SELECT 1 FROM construction_material_packages x WHERE x.construction_material_id=cm.id AND x.offer_package_id=op.id);
